// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint96 amount, bytes calldata data) public {
        vm.assume(actor != address(this));
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.sendMoney(address(0), amount, data) {} catch {}
        vm.prank(actor);
        try c.withdrawAll() { assertTrue(false); } catch { assertTrue(true); }
    }
}
